import * as vscode from 'vscode';
import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';

interface SessionData {
    id: string;
    timestamp: number;
    data: any;
}

export function activate(context: vscode.ExtensionContext) {
    console.log('Suucha extension is now active!');

    // Get configuration
    const config = vscode.workspace.getConfiguration('suucha');
    const syncInterval = config.get<number>('syncInterval', 5);
    const maxBackups = config.get<number>('maxBackups', 10);
    const encryptionEnabled = config.get<boolean>('encryptionEnabled', true);

    // Create storage directory
    const storageDir = path.join(context.globalStorageUri.fsPath, 'sessions');
    if (!fs.existsSync(storageDir)) {
        fs.mkdirSync(storageDir, { recursive: true });
    }

    // Session manager class
    class SessionManager {
        private sessions: Map<string, SessionData> = new Map();
        private syncTimer: NodeJS.Timeout | null = null;
        private encryptionKey: string;

        constructor() {
            this.encryptionKey = crypto.randomBytes(32).toString('hex');
            this.loadSessions();
            this.startSyncTimer();
        }

        private loadSessions(): void {
            try {
                const files = fs.readdirSync(storageDir);
                files.forEach(file => {
                    const filePath = path.join(storageDir, file);
                    const rawData = fs.readFileSync(filePath);

                    let data: SessionData;
                    if (encryptionEnabled) {
                        // In a real implementation, you would use proper encryption/decryption
                        data = JSON.parse(this.decrypt(rawData.toString()));
                    } else {
                        data = JSON.parse(rawData.toString());
                    }

                    this.sessions.set(data.id, data);
                });

                this.cleanupOldSessions(maxBackups);
            } catch (error) {
                console.error('Failed to load sessions:', error);
            }
        }

        private saveSession(session: SessionData): void {
            const fileName = `${session.id}.json`;
            const filePath = path.join(storageDir, fileName);

            let dataToSave = JSON.stringify(session);
            if (encryptionEnabled) {
                // In a real implementation, you would use proper encryption/decryption
                dataToSave = this.encrypt(dataToSave);
            }

            fs.writeFileSync(filePath, dataToSave);
            this.sessions.set(session.id, session);
        }

        private encrypt(data: string): string {
            // Placeholder for actual encryption implementation
            return Buffer.from(data).toString('base64');
        }

        private decrypt(data: string): string {
            // Placeholder for actual decryption implementation
            return Buffer.from(data, 'base64').toString();
        }

        private cleanupOldSessions(maxBackups: number): void {
            const sessions = Array.from(this.sessions.values())
                .sort((a, b) => b.timestamp - a.timestamp);

            if (sessions.length > maxBackups) {
                const sessionsToRemove = sessions.slice(maxBackups);
                sessionsToRemove.forEach(session => {
                    const filePath = path.join(storageDir, `${session.id}.json`);
                    if (fs.existsSync(filePath)) {
                        fs.unlinkSync(filePath);
                    }
                    this.sessions.delete(session.id);
                });
            }
        }

        private startSyncTimer(): void {
            if (this.syncTimer) {
                clearInterval(this.syncTimer);
            }

            this.syncTimer = setInterval(() => {
                this.syncSessions();
            }, syncInterval * 60 * 1000);
        }

        public syncSessions(): void {
            console.log('Syncing Claude Code sessions...');

            // Get current Claude Code sessions
            // This would typically involve calling the Claude Code API
            const currentSessions = this.getCurrentSessions();

            currentSessions.forEach(session => {
                if (!this.sessions.has(session.id) || 
                    session.timestamp > this.sessions.get(session.id)!.timestamp) {
                    this.saveSession(session);
                }
            });

            this.cleanupOldSessions(maxBackups);
        }

        private getCurrentSessions(): SessionData[] {
            // This is a placeholder - in a real implementation,
            // you would fetch actual Claude Code sessions
            return [
                {
                    id: 'session-1',
                    timestamp: Date.now(),
                    data: { /* session data */ }
                }
            ];
        }

        public dispose(): void {
            if (this.syncTimer) {
                clearInterval(this.syncTimer);
                this.syncTimer = null;
            }
        }
    }

    // Create session manager instance
    const sessionManager = new SessionManager();

    // Register commands
    let disposable = vscode.commands.registerCommand('suucha.syncNow', () => {
        sessionManager.syncSessions();
        vscode.window.showInformationMessage('Claude Code sessions synced successfully!');
    });

    context.subscriptions.push(disposable);

    // Register a status bar item
    const statusBar = vscode.window.createStatusBarItem(vscode.StatusBarAlignment.Right, 100);
    statusBar.text = '$(sync) Suucha';
    statusBar.tooltip = 'Claude Code Session Sync';
    statusBar.show();
    context.subscriptions.push(statusBar);

    // Cleanup on deactivate
    context.subscriptions.push({
        dispose: () => {
            sessionManager.dispose();
            statusBar.dispose();
        }
    });
}

export function deactivate() {
    console.log('Suucha extension is now deactivated!');
}
